using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Authorization;using Microsoft.EntityFrameworkCore;using System.Security.Claims;using EMedicine.Api.Data;using EMedicine.Api.Models;using EMedicine.Api.DTOs;
namespace EMedicine.Api.Controllers;
[ApiController][Authorize][Route("api/cart")]public class CartController(AppDbContext db):ControllerBase{int Uid=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
[HttpGet]public async Task<IActionResult> List()=>Ok(await db.Cart.Include(x=>x.Medicine).Where(x=>x.UserId==Uid).ToListAsync());
[HttpPost]public async Task<IActionResult> Add(CartRequest r){if(r.Quantity<1)return BadRequest("Quantity must be positive");var m=await db.Medicines.FindAsync(r.MedicineId);if(m==null||!m.Active||m.ExpDate.Date<DateTime.UtcNow.Date)return BadRequest("Medicine unavailable");var item=await db.Cart.FirstOrDefaultAsync(x=>x.UserId==Uid&&x.MedicineId==r.MedicineId);if(r.Quantity+(item?.Quantity??0)>m.Quantity)return BadRequest("Not enough stock");if(item==null)db.Cart.Add(new CartItem{UserId=Uid,MedicineId=r.MedicineId,Quantity=r.Quantity});else item.Quantity+=r.Quantity;await db.SaveChangesAsync();return Ok();}
[HttpDelete("{id:int}")]public async Task<IActionResult> Remove(int id){var c=await db.Cart.FirstOrDefaultAsync(x=>x.Id==id&&x.UserId==Uid);if(c==null)return NotFound();db.Cart.Remove(c);await db.SaveChangesAsync();return NoContent();}}
